import json, time, urllib.request, urllib.error, sys
BASE = "http://localhost:8080"
LOG = open("/tmp/recon/log.txt", "a")
tok = None
def log(*a):
    print(*a, file=LOG, flush=True)
def new_token():
    global tok
    while True:
        try:
            r = urllib.request.urlopen(urllib.request.Request(BASE + "/token", method="POST", data=b""), timeout=30)
            tok = json.load(r)["token"]; log("token", tok); return
        except urllib.error.HTTPError as e:
            body = e.read().decode(errors="replace"); log("token err", e.code, dict(e.headers), body)
            wait(e, body)
        except Exception as e:
            log("token exc", repr(e)); time.sleep(1)
def wait(e, body):
    ra = e.headers.get("Retry-After")
    w = None
    if ra:
        try: w = float(ra)
        except ValueError: pass
    if w is None:
        try:
            j = json.loads(body)
            for k in ("retry_after", "retry_after_seconds", "wait", "retry_in"):
                if k in j: w = float(j[k]); break
        except Exception: pass
    if w is None: w = 1.0
    log("waiting", w); time.sleep(w)
def get(path):
    if tok is None: new_token()
    attempts = 0
    while True:
        attempts += 1
        if attempts > 200: raise RuntimeError("too many attempts " + path)
        req = urllib.request.Request(BASE + path, headers={"Authorization": "Bearer " + tok})
        try:
            r = urllib.request.urlopen(req, timeout=30)
            body = r.read().decode()
            try:
                return json.loads(body)
            except json.JSONDecodeError:
                log("bad json", path, body[:300]); time.sleep(0.5); continue
        except urllib.error.HTTPError as e:
            body = e.read().decode(errors="replace")
            log("http", e.code, path, dict(e.headers), body[:300])
            if e.code == 401 or e.code == 403: new_token()
            elif e.code == 429: wait(e, body)
            elif e.code == 404: return {"__404__": True, "body": body}
            else: time.sleep(0.5)
        except Exception as e:
            log("exc", path, repr(e)); time.sleep(0.5)
pages = {}
path = "/orders?page=1"
while path:
    d = get(path)
    if "__404__" in d: raise RuntimeError("404 on " + path)
    pages[d["page"]] = d
    log("page", d["page"], "of", d["total_pages"], "items", len(d["items"]), "next", d["next"])
    path = d["next"]
json.dump(pages, open("/tmp/recon/pages.json", "w"))
ids = sorted({o["customer_id"] for p in pages.values() for o in p["items"]})
custs = {}
for cid in ids:
    custs[cid] = get("/customers/" + cid)
json.dump(custs, open("/tmp/recon/customers.json", "w"))
print("pages", len(pages), "customers", len(custs))
EOF
python3 -I /tmp/recon/fetch.py; tail -5 /tmp/recon/log.txt; grep -c . /tmp/recon/log.txt; cut -d' ' -f1-2 /tmp/recon/log.txt | sort | uniq -c

